package br.com.admeclesial.application.financeiro; import org.springframework.beans.factory.annotation.Autowired; import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.ContaFinanceiraRepository; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class ContaFinanceiraApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final ContaFinanceiraRepository repo; final OrganizacaoEclesialRepository org; public ContaFinanceiraApplicationService(ContaFinanceiraRepository r,OrganizacaoEclesialRepository o){repo=r;org=o;} @Transactional public ContaFinanceira salvar(UUID uuid,UUID orgUuid,String nome,TipoContaFinanceira tipo,String banco,String agencia,String numero,boolean ativo){if(seguranca!=null)seguranca.validarAcesso(orgUuid);if(uuid!=null){var atual=repo.findByUuid(uuid).orElseThrow();if(seguranca!=null)seguranca.validarAcessoId(atual.getOrganizacaoEclesialId());}var o=org.findByUuid(orgUuid).orElseThrow(()->new IllegalArgumentException("Organização não encontrada.")); if(!o.isAtivo())throw new IllegalArgumentException("Organização inativa."); var e=uuid==null?new ContaFinanceira():repo.findByUuid(uuid).orElseThrow();e.setOrganizacaoEclesialId(o.getId());e.setNome(nome.trim());e.setTipo(tipo);e.setBanco(banco);e.setAgencia(agencia);e.setNumero(numero);e.setAtivo(ativo);return repo.save(e);} @Transactional(readOnly=true) public List<ContaFinanceira> listar(){return repo.findAllByOrderByNomeAsc().stream().filter(e -> { try { if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoEclesialId()); return true; } catch (org.springframework.security.access.AccessDeniedException ex) { return false; }}).toList();} @Transactional(readOnly=true) public ContaFinanceira buscar(UUID u){var e=repo.findByUuid(u).orElseThrow();if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoEclesialId());return e;}}